/* ---------- static background ---------- */
function buildBg() {
  const m = bgM, w = W + 2 * m, h = H + 2 * m;
  bg = document.createElement('canvas');
  bg.width = Math.round(w * dpr);
  bg.height = Math.round(h * dpr);
  const g = bg.getContext('2d');
  g.scale(dpr, dpr);
  g.translate(m, m);
  const R = base.R, cx = base.cx, cy = base.cy;
  const yh = Math.max(H * 0.16, cy - 1.3 * R);

  let gr = g.createLinearGradient(0, -m, 0, yh);
  gr.addColorStop(0, '#030202');
  gr.addColorStop(1, '#0d0806');
  g.fillStyle = gr;
  g.fillRect(-m, -m, w, yh + m);

  gr = g.createLinearGradient(0, yh, 0, H + m);
  gr.addColorStop(0, '#0c0705');
  gr.addColorStop(0.35, '#150d08');
  gr.addColorStop(1, '#20130b');
  g.fillStyle = gr;
  g.fillRect(-m, yh, w, H + m - yh);

  const rnd = rng(77);
  const span = H + m - yh;
  for (let i = 0; i < 46; i++) {
    const f = i / 46;
    const y0 = yh + span * Math.pow(f, 1.6);
    const persp = 0.3 + f * 1.4;
    const amp = (0.6 + rnd() * 1.6) * persp, fr = 0.002 + rnd() * 0.004, ph = rnd() * TAU;
    g.beginPath();
    for (let x = -m; x <= W + m; x += 24) {
      const y = y0 + Math.sin(x * fr + ph) * amp;
      if (x === -m) g.moveTo(x, y); else g.lineTo(x, y);
    }
    g.strokeStyle = rnd() < 0.55 ? 'rgba(0,0,0,' + (0.10 + rnd() * 0.16) + ')' : 'rgba(120,70,30,' + (0.03 + rnd() * 0.05) + ')';
    g.lineWidth = (0.6 + rnd() * 1.4) * persp;
    g.stroke();
  }
  for (const f of [0.12, 0.3, 0.5, 0.72, 0.95]) {
    const y = yh + span * Math.pow(f, 1.6);
    g.strokeStyle = 'rgba(0,0,0,0.38)';
    g.lineWidth = 1 + f * 2.5;
    g.beginPath(); g.moveTo(-m, y); g.lineTo(W + m, y); g.stroke();
  }

  gr = g.createLinearGradient(0, yh, 0, yh + R * 0.6);
  gr.addColorStop(0, 'rgba(8,5,4,0.9)');
  gr.addColorStop(1, 'rgba(8,5,4,0)');
  g.fillStyle = gr;
  g.fillRect(-m, yh, w, R * 0.6);

  gr = g.createLinearGradient(0, yh - R * 0.1, 0, yh + R * 0.1);
  gr.addColorStop(0, 'rgba(255,160,80,0)');
  gr.addColorStop(0.5, 'rgba(255,160,80,0.05)');
  gr.addColorStop(1, 'rgba(255,160,80,0)');
  g.fillStyle = gr;
  g.fillRect(-m, yh - R * 0.1, w, R * 0.2);

  gr = g.createRadialGradient(cx, yh, 0, cx, yh, R * 1.7);
  gr.addColorStop(0, 'rgba(255,140,60,0.10)');
  gr.addColorStop(1, 'rgba(255,140,60,0)');
  g.fillStyle = gr;
  g.fillRect(-m, -m, w, h);

  for (let i = 0; i < 10; i++) {
    const x = rnd() * W, y = yh * (0.2 + rnd() * 0.7), rad = 18 + rnd() * 46;
    const col = rnd() < 0.6 ? [255, 150, 60] : [255, 90, 50], a = 0.03 + rnd() * 0.05;
    gr = g.createRadialGradient(x, y, 0, x, y, rad);
    gr.addColorStop(0, rgbaStr(col, a * 0.6));
    gr.addColorStop(0.75, rgbaStr(col, a));
    gr.addColorStop(1, rgbaStr(col, 0));
    g.fillStyle = gr;
    g.beginPath(); g.arc(x, y, rad, 0, TAU); g.fill();
  }
}

/* ---------- ripples ---------- */
const ripples = [];
let ambientTimer = 0.4;
function addRipple(u, v, amp, speed, life) {
  if (ripples.length > 26) ripples.shift();
  ripples.push({ u, v, amp, speed, life, age: 0 });
}
function ripAt(u, v) {
  let s = 0;
  for (let i = 0; i < ripples.length; i++) {
    const r = ripples[i];
    const du = u - r.u, dv = v - r.v;
    const x = (Math.sqrt(du * du + dv * dv) - r.age * r.speed) / 0.14;
    if (x > 3 || x < -3) continue;
    s += r.amp * (1 - r.age / r.life) * Math.exp(-x * x);
  }
  return s;
}
function bobAt(u, v, ph, time) {
  return ripAt(u, v) * 0.016 + Math.sin(time * 1.15 + ph) * 0.0012;
}

/* ---------- steam ---------- */
const steam = [];
let emitAcc = 0;
function spawnSteam(x, y, burst) {
  if (steam.length >= 230) return;
  const R = B.R;
  steam.push({
    x, y,
    vx: (Math.random() - 0.5) * R * 0.06,
    vy: -R * (0.10 + Math.random() * 0.10) * (burst ? 1.6 : 1),
    age: 0, life: 5 + Math.random() * 3.5,
    r0: R * (0.05 + Math.random() * 0.05), r1: R * (0.22 + Math.random() * 0.20),
    peak: 0.05 + Math.random() * 0.06,
    seed: Math.random(), rot: Math.random() * TAU, spin: (Math.random() - 0.5) * 0.5,
    v: (Math.random() * 3) | 0
  });
}
function emitFromBroth(burst) {
  const a = Math.random() * TAU, d = Math.sqrt(Math.random()) * 0.72;
  proj(Math.cos(a) * d, Math.sin(a) * d * 0.8 - 0.05, 0.02);
  spawnSteam(PX, PY, burst);
}
function stepSteam(dt, time, usePtr) {
  const R = B.R;
  const breath = 0.5 + 0.5 * Math.sin(time * 0.55);
  emitAcc += (20 + 12 * breath) * dt;
  const sp = Math.hypot(ptr.vx, ptr.vy), pf = Math.min(1, sp / 700);
  if (usePtr && ptr.active && ptr.over && sp > 150) emitAcc += 25 * dt * pf;
  while (emitAcc >= 1) { emitAcc -= 1; emitFromBroth(false); }
  const wind = Math.sin(time * 0.11) * 0.03 * R + Math.sin(time * 0.37 + 1.0) * 0.015 * R;
  const rad = R * 0.9, rad2 = rad * rad;
  for (let i = steam.length - 1; i >= 0; i--) {
    const p = steam[i];
    p.age += dt;
    if (p.age >= p.life) { steam[i] = steam[steam.length - 1]; steam.pop(); continue; }
    const yn = Math.max(0, (B.bcy - p.y) / R);
    const tvy = -R * (0.16 + 0.10 * Math.min(1, p.age / 2.2));
    p.vy += (tvy - p.vy) * Math.min(1, dt * 0.9);
    const tvx = wind * (0.3 + yn) +
      (Math.sin(yn * 3.2 + time * 0.8 + p.seed * 6.283) * 0.085 + Math.sin(yn * 7.1 - time * 1.3 + p.seed * 17.0) * 0.035) * R * (0.35 + yn * 0.6);
    p.vx += (tvx - p.vx) * Math.min(1, dt * 1.5);
    if (usePtr && ptr.active) {
      const dx = p.x - ptr.x, dy = p.y - ptr.y, d2 = dx * dx + dy * dy;
      if (d2 < rad2) {
        const d = Math.sqrt(d2) + 1, f = 1 - d / rad, ff = f * f * dt;
        p.vx += ptr.vx * ff * 3.0 + (dx / d) * R * 0.9 * ff * pf;
        p.vy += ptr.vy * ff * 2.0 + (dy / d) * R * 0.6 * ff * pf;
      }
    }
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.rot += p.spin * dt;
  }
}
function prewarmSteam(sec) {
  steam.length = 0;
  emitAcc = 0;
  const dt = 1 / 30, n = Math.round(sec / dt);
  let tt = T - sec;
  for (let i = 0; i < n; i++) { tt += dt; stepSteam(dt, tt, false); }
}

/* ---------- motes ---------- */
const motes = [];
function initMotes() {
  motes.length = 0;
  const n = Math.round(clamp(W * H / 24000, 26, 72));
  for (let i = 0; i < n; i++) {
    motes.push({
      x: Math.random() * W, y: Math.random() * H, r: 0.5 + Math.random() * 1.3,
      vy: -(5 + Math.random() * 14), ph: Math.random() * TAU, tw: 1 + Math.random() * 2.5, ex: 0, ey: 0
    });
  }
}
function stepMotes(dt) {
  const decay = Math.exp(-1.5 * dt), rad = B.R * 0.7;
  for (let i = 0; i < motes.length; i++) {
    const m = motes[i];
    m.x += (Math.sin(T * 0.5 + m.ph) * 6 + m.ex) * dt;
    m.y += (m.vy + m.ey) * dt;
    m.ex *= decay; m.ey *= decay;
    if (ptr.active) {
      const dx = m.x - ptr.x, dy = m.y - ptr.y, d2 = dx * dx + dy * dy;
      if (d2 < rad * rad) {
        const f = 1 - Math.sqrt(d2) / rad;
        m.ex += ptr.vx * f * f * dt * 4;
        m.ey += ptr.vy * f * f * dt * 4;
      }
    }
    if (m.y < -10) { m.y = H + 10; m.x = Math.random() * W; }
    if (m.x < -10) m.x = W + 10;
    if (m.x > W + 10) m.x = -10;
  }
}

/* ---------- update ---------- */
function update(dt) {
  if (ptr.active && ptr.touch && T - ptr.t > 2.5) ptr.active = false;
  const dec = Math.exp(-5 * dt);
  ptr.vx *= dec; ptr.vy *= dec;

  let tlx, tly, tpx, tpy;
  if (ptr.active) {
    tlx = ptr.x; tly = ptr.y;
    tpx = (ptr.x / W - 0.5) * 2; tpy = (ptr.y / H - 0.5) * 2;
  } else {
    tlx = base.cx - 0.45 * base.R + Math.sin(T * 0.23) * 0.5 * base.R;
    tly = base.cy - 1.0 * base.R + Math.cos(T * 0.19) * 0.15 * base.R;
    tpx = Math.sin(T * 0.17) * 0.35; tpy = Math.cos(T * 0.13) * 0.2;
  }
  const kl = 1 - Math.exp(-dt * 3.5), kp = 1 - Math.exp(-dt * 2.2);
  light.x += (tlx - light.x) * kl; light.y += (tly - light.y) * kl;
  par.x += (clamp(tpx, -1, 1) - par.x) * kp; par.y += (clamp(tpy, -1, 1) - par.y) * kp;
  layout();

  for (let i = ripples.length - 1; i >= 0; i--) {
    ripples[i].age += dt;
    if (ripples[i].age > ripples[i].life) ripples.splice(i, 1);
  }
  ambientTimer -= dt;
  if (ambientTimer <= 0) {
    ambientTimer = 0.35 + Math.random() * 0.7;
    const a = Math.random() * TAU, d = Math.sqrt(Math.random()) * 0.8;
    addRipple(Math.cos(a) * d, Math.sin(a) * d, 0.35, 0.16, 2.4);
  }

  ptr.over = false;
  if (ptr.active) {
    const u = (ptr.x - B.bcx) / B.brx, v = (ptr.y - B.bcy) / B.bry;
    if (u * u + v * v < 0.8 && ptr.y < B.cy + B.iry * 0.8) {
      ptr.over = true;
      const sp = Math.hypot(ptr.vx, ptr.vy);
      if (sp > 140 && T - ptr.lastRip > 0.1) {
        addRipple(u, v, clamp(sp / 1500, 0.3, 0.95), 0.5, 2.0);
        ptr.lastRip = T;
      }
    }
  }

  stepSteam(dt, T, true);
  stepMotes(dt);
}

/*@@PART3@@*/

/* ---------- ambient ---------- */
function drawAmbient() {
  ctx.globalCompositeOperation = 'lighter';
  const gy = B.cy - B.R * 0.5;
  let g = ctx.createRadialGradient(B.cx, gy, 0, B.cx, gy, B.R * 2.2);
  g.addColorStop(0, 'rgba(255,140,55,' + (0.13 * flick) + ')');
  g.addColorStop(0.45, 'rgba(200,90,30,' + (0.05 * flick) + ')');
  g.addColorStop(1, 'rgba(150,60,20,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  g = ctx.createRadialGradient(light.x, light.y, 0, light.x, light.y, B.R * 1.1);
  g.addColorStop(0, 'rgba(255,175,95,0.07)');
  g.addColorStop(1, 'rgba(255,175,95,0)');
  ctx.fillStyle = g;
  ctx.fillRect(light.x - B.R * 1.1, light.y - B.R * 1.1, B.R * 2.2, B.R * 2.2);
  ctx.globalCompositeOperation = 'source-over';

  const rr = Math.max(W, H) * 0.32;
  for (let i = 0; i < 4; i++) {
    const hx = W * (0.15 + 0.23 * i) + Math.sin(T * 0.04 + i * 1.7) * W * 0.06;
    const hy = H * (0.30 + 0.1 * Math.sin(i * 2.1)) + Math.cos(T * 0.05 + i) * H * 0.03;
    g = ctx.createRadialGradient(hx, hy, 0, hx, hy, rr);
    g.addColorStop(0, 'rgba(200,170,150,0.035)');
    g.addColorStop(1, 'rgba(200,170,150,0)');
    ctx.fillStyle = g;
    ctx.fillRect(hx - rr, hy - rr, rr * 2, rr * 2);
  }
}

/* ---------- bowl ---------- */
function drawBand() {
  const cx = B.cx, cy = B.cy, k = B.k, Hb = B.Hb;
  const ta = 0.16, tb = 0.235;
  ctx.lineWidth = 1.1;
  ctx.lineJoin = 'miter';
  ctx.strokeStyle = 'rgba(216,174,98,0.55)';
  for (const t of [0.125, 0.275]) {
    const w = wAt(t);
    ctx.beginPath();
    ctx.ellipse(cx, cy + Hb * t, w, w * k, 0, 0, Math.PI, false);
    ctx.stroke();
  }
  const NS = 44;
  const pt = (th, t) => { const w = wAt(t); return [cx + w * Math.cos(th), cy + Hb * t + w * k * Math.sin(th)]; };
  ctx.beginPath();
  for (let j = 0; j < NS; j++) {
    const even = j % 2 === 0;
    const L0 = even ? ta : tb, L1 = even ? tb : ta;
    const a = pt(Math.PI * j / NS, L0), b = pt(Math.PI * (j + 1) / NS, L0), c = pt(Math.PI * (j + 1) / NS, L1);
    if (j === 0) ctx.moveTo(a[0], a[1]);
    ctx.lineTo(b[0], b[1]);
    ctx.lineTo(c[0], c[1]);
  }
  ctx.strokeStyle = 'rgba(216,174,98,0.5)';
  ctx.stroke();
  ctx.lineJoin = 'round';
}

function drawBowl() {
  const R = B.R, k = B.k, cx = B.cx, cy = B.cy, Hb = B.Hb;
  const fy = cy + Hb + R * 0.075;
  let g;

  ctx.save();
  ctx.translate(cx, fy);
  ctx.scale(1, k * 1.15);
  g = ctx.createRadialGradient(0, 0, R * 0.3, 0, 0, R * 2.7);
  g.addColorStop(0, 'rgba(255,140,55,' + (0.17 * flick) + ')');
  g.addColorStop(0.5, 'rgba(200,90,30,' + (0.06 * flick) + ')');
  g.addColorStop(1, 'rgba(200,90,30,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(0, 0, R * 2.7, 0, TAU); ctx.fill();
  ctx.restore();

  ctx.save();
  ctx.translate(cx - LX * R * 0.10, fy + R * 0.01);
  ctx.scale(1, k);
  g = ctx.createRadialGradient(0, 0, R * 0.25, 0, 0, R * 1.3);
  g.addColorStop(0, 'rgba(0,0,0,0.9)');
  g.addColorStop(0.45, 'rgba(0,0,0,0.55)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(0, 0, R * 1.3, 0, TAU); ctx.fill();
  g = ctx.createRadialGradient(0, 0, 0, 0, 0, R * 0.55);
  g.addColorStop(0, 'rgba(0,0,0,0.85)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(0, 0, R * 0.55, 0, TAU); ctx.fill();
  ctx.restore();

  const fw = R * B.f * 0.86, fh = R * 0.075, ft = cy + Hb - R * 0.012;
  ctx.beginPath();
  ctx.moveTo(cx - fw, ft);
  ctx.lineTo(cx - fw, ft + fh);
  ctx.ellipse(cx, ft + fh, fw, fw * k, 0, Math.PI, 0, true);
  ctx.lineTo(cx + fw, ft);
  ctx.closePath();
  g = ctx.createLinearGradient(cx - fw, 0, cx + fw, 0);
  g.addColorStop(0, '#120c09');
  g.addColorStop(clamp(0.5 + LX * 0.25, 0.1, 0.9), '#3a281c');
  g.addColorStop(1, '#0c0806');
  ctx.fillStyle = g;
  ctx.fill();

  const N = 32;
  ctx.beginPath();
  ctx.moveTo(cx - R, cy);
  for (let i = 1; i <= N; i++) { const t = i / N; ctx.lineTo(cx - wAt(t), cy + Hb * t); }
  ctx.ellipse(cx, cy + Hb, wAt(1), wAt(1) * k, 0, Math.PI, 0, true);
  for (let i = N - 1; i >= 0; i--) { const t = i / N; ctx.lineTo(cx + wAt(t), cy + Hb * t); }
  ctx.ellipse(cx, cy, R, R * k, 0, 0, Math.PI, false);
  ctx.closePath();

  const hp = clamp(0.5 + LX * 0.28, 0.14, 0.86);
  g = ctx.createLinearGradient(cx - R, 0, cx + R, 0);
  g.addColorStop(0, '#050506');
  g.addColorStop(clamp(hp - 0.26, 0.02, 0.98), '#0f1015');
  g.addColorStop(hp, '#30333d');
  g.addColorStop(clamp(hp + 0.26, 0.02, 0.98), '#0d0e12');
  g.addColorStop(1, '#040405');
  ctx.fillStyle = g;
  ctx.fill();

  ctx.save();
  ctx.clip();
  g = ctx.createLinearGradient(0, cy, 0, cy + Hb + R * 0.2);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.6, 'rgba(0,0,0,0.25)');
  g.addColorStop(1, 'rgba(0,0,0,0.6)');
  ctx.fillStyle = g;
  ctx.fillRect(cx - R - 2, cy, R * 2 + 4, Hb + R * 0.5);

  g = ctx.createLinearGradient(0, cy + Hb * 0.6, 0, cy + Hb + R * 0.2);
  g.addColorStop(0, 'rgba(190,90,30,0)');
  g.addColorStop(1, 'rgba(190,90,30,' + (0.20 * flick) + ')');
  ctx.fillStyle = g;
  ctx.fillRect(cx - R - 2, cy + Hb * 0.6, R * 2 + 4, Hb * 0.4 + R * 0.5);

  const xf = clamp(LX * 0.55, -0.86, 0.86);
  const sq = Math.sqrt(1 - xf * xf);
  const wm = 0.35 + 0.65 * sq;
  const inten = 0.75 + 0.25 * flick;
  const widths = [0.11, 0.075, 0.045, 0.02], alphas = [0.025, 0.035, 0.06, 0.10];
  ctx.lineCap = 'round';
  for (let j = 0; j < 4; j++) {
    ctx.beginPath();
    for (let i = 0; i <= 14; i++) {
      const t = 0.10 + i / 14 * 0.62;
      const w = wAt(t);
      const x = cx + xf * w * 0.92, y = cy + Hb * t + k * w * sq;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.lineWidth = widths[j] * R * wm;
    ctx.strokeStyle = 'rgba(255,236,214,' + (alphas[j] * inten) + ')';
    ctx.stroke();
  }
  drawBand();
  ctx.restore();

  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(1, k);
  let rg;
  if (ctx.createConicGradient) {
    const ang = Math.atan2((light.y - cy) / k, light.x - cx);
    rg = ctx.createConicGradient(ang - Math.PI, 0, 0);
    rg.addColorStop(0, '#0b0b0e');
    rg.addColorStop(0.30, '#111218');
    rg.addColorStop(0.44, '#1a1b22');
    rg.addColorStop(0.5, '#7d7368');
    rg.addColorStop(0.56, '#1a1b22');
    rg.addColorStop(0.70, '#111218');
    rg.addColorStop(1, '#0b0b0e');
  } else {
    rg = ctx.createLinearGradient(-R, 0, R, 0);
    rg.addColorStop(0, '#0b0b0e');
    rg.addColorStop(hp, '#3a3b44');
    rg.addColorStop(1, '#0b0b0e');
  }
  ctx.beginPath();
  ctx.moveTo(R, 0); ctx.arc(0, 0, R, 0, TAU); ctx.closePath();
  ctx.moveTo(B.irx, 0); ctx.arc(0, 0, B.irx, 0, TAU); ctx.closePath();
  ctx.fillStyle = rg;
  ctx.fill('evenodd');
  ctx.restore();

  ctx.lineWidth = 1;
  ctx.strokeStyle = 'rgba(255,225,180,0.16)';
  ctx.beginPath(); ctx.ellipse(cx, cy, R, R * k, 0, 0, TAU); ctx.stroke();
  ctx.strokeStyle = 'rgba(215,170,95,0.35)';
  ctx.beginPath(); ctx.ellipse(cx, cy, B.irx + 0.5, B.iry + 0.5, 0, 0, TAU); ctx.stroke();

  ctx.save();
  ctx.beginPath(); ctx.ellipse(cx, cy, B.irx, B.iry, 0, 0, TAU); ctx.clip();
  g = ctx.createLinearGradient(0, cy - B.iry, 0, B.bcy - B.bry + 3);
  g.addColorStop(0, '#160304');
  g.addColorStop(0.45, '#520c09');
  g.addColorStop(1, '#a0401a');
  ctx.fillStyle = g;
  ctx.fillRect(cx - B.irx, cy - B.iry, B.irx * 2, B.iry * 2);
  ctx.restore();
}

/* ---------- broth ---------- */
function drawBroth() {
  const cx = B.cx, cy = B.cy, irx = B.irx, iry = B.iry, bcx = B.bcx, bcy = B.bcy, brx = B.brx, bry = B.bry, k = B.k;
  ctx.save();
  ctx.beginPath(); ctx.ellipse(cx, cy, irx, iry, 0, 0, TAU); ctx.clip();

  ctx.save();
  ctx.translate(bcx, bcy);
  ctx.scale(1, k);
  const ox = clamp(LX * 0.22, -0.3, 0.3) * brx, oy = clamp(LY * 0.12, -0.25, 0.15) * brx;
  let g = ctx.createRadialGradient(ox, oy, 0, 0, 0, brx);
  g.addColorStop(0, '#cf8b34');
  g.addColorStop(0.35, '#b9701f');
  g.addColorStop(0.7, '#8c4a14');
  g.addColorStop(0.93, '#5b2a0b');
  g.addColorStop(1, '#3a1a08');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(0, 0, brx, 0, TAU); ctx.fill();

  for (let i = 0; i < 6; i++) {
    const a = T * (0.045 + 0.012 * i) * (i % 2 ? -1 : 1) + i * 1.05;
    const d = brx * (0.28 + 0.30 * ((i * 0.37) % 1));
    const bx = Math.cos(a) * d, by = Math.sin(a) * d;
    const rr = brx * (0.34 + 0.10 * ((i * 0.53) % 1));
    const lightBlob = i % 2 === 0;
    g = ctx.createRadialGradient(bx, by, 0, bx, by, rr);
    g.addColorStop(0, lightBlob ? 'rgba(255,205,120,0.13)' : 'rgba(70,26,4,0.16)');
    g.addColorStop(1, lightBlob ? 'rgba(255,205,120,0)' : 'rgba(70,26,4,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(bx, by, rr, 0, TAU); ctx.fill();
  }

  g = ctx.createRadialGradient(0, 0, brx * 0.62, 0, 0, brx);
  g.addColorStop(0, 'rgba(25,8,0,0)');
  g.addColorStop(0.7, 'rgba(25,8,0,0.16)');
  g.addColorStop(1, 'rgba(15,4,0,0.55)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(0, 0, brx, 0, TAU); ctx.fill();

  ctx.strokeStyle = 'rgba(255,208,140,0.35)';
  ctx.lineWidth = 2.6;
  ctx.beginPath(); ctx.arc(0, 0, brx - 0.5, Math.PI * 1.03, Math.PI * 1.97); ctx.stroke();

  ctx.save();
  ctx.beginPath(); ctx.arc(0, 0, brx, 0, TAU); ctx.clip();
  const hx = clamp(LX * 0.28, -0.55, 0.55) * brx, hy = clamp(LY * 0.32, -0.55, 0.4) * brx;
  g = ctx.createRadialGradient(hx, hy, 0, hx, hy, brx * 0.55);
  g.addColorStop(0, 'rgba(255,226,170,' + (0.34 * flick) + ')');
  g.addColorStop(0.35, 'rgba(255,200,120,' + (0.14 * flick) + ')');
  g.addColorStop(1, 'rgba(255,190,100,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(hx, hy, brx * 0.55, 0, TAU); ctx.fill();
  g = ctx.createRadialGradient(hx, hy, 0, hx, hy, brx * 0.13);
  g.addColorStop(0, 'rgba(255,246,222,' + (0.62 * flick) + ')');
  g.addColorStop(1, 'rgba(255,240,200,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(hx, hy, brx * 0.13, 0, TAU); ctx.fill();
  ctx.restore();
  ctx.restore();

  for (let i = 0; i < ripples.length; i++) {
    const r = ripples[i];
    const rad = r.age * r.speed;
    if (rad < 0.02) continue;
    const a = r.amp * (1 - r.age / r.life);
    if (a < 0.03) continue;
    proj(r.u, r.v, 0);
    const rx = rad * brx, ry = rad * bry;
    ctx.lineWidth = 1.4;
    ctx.strokeStyle = 'rgba(255,228,176,' + (a * 0.45).toFixed(3) + ')';
    ctx.beginPath(); ctx.ellipse(PX, PY, rx, ry, 0, 0, TAU); ctx.stroke();
    ctx.lineWidth = 2.4;
    ctx.strokeStyle = 'rgba(50,16,2,' + (a * 0.22).toFixed(3) + ')';
    ctx.beginPath(); ctx.ellipse(PX, PY + 1.2, rx * 0.94, ry * 0.94, 0, 0, TAU); ctx.stroke();
  }
  ctx.restore();
}

function drawLip() {
  ctx.save();
  ctx.beginPath(); ctx.ellipse(B.cx, B.cy, B.irx, B.iry, 0, 0, TAU); ctx.clip();
  ctx.translate(B.cx, B.cy);
  ctx.scale(1, B.k);
  const g = ctx.createRadialGradient(0, 0, B.irx * 0.82, 0, 0, B.irx);
  g.addColorStop(0, 'rgba(12,3,0,0)');
  g.addColorStop(1, 'rgba(10,2,0,0.5)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(0, 0, B.irx, 0, TAU); ctx.fill();
  ctx.restore();
  ctx.strokeStyle = 'rgba(255,222,176,0.24)';
  ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.ellipse(B.cx, B.cy, B.irx - 0.6, B.iry - 0.6, 0, 0.05, Math.PI - 0.05, false); ctx.stroke();
}

