function drawBeads(time) {
  const R = B.R, k = B.k, bl = S.beads;
  ctx.lineWidth = 0.8;
  for (let i = 0; i < bl.length; i++) {
    const b = bl[i];
    const a = b.a0 + time * b.w;
    proj(Math.cos(a) * b.d, Math.sin(a) * b.d, 0.001);
    const rx = b.r * R, ry = Math.max(0.3, rx * k);
    if (b.chili) {
      ctx.fillStyle = 'rgba(206,56,18,0.42)';
      ctx.strokeStyle = 'rgba(255,128,64,0.55)';
    } else {
      ctx.fillStyle = 'rgba(255,196,96,0.17)';
      ctx.strokeStyle = 'rgba(255,228,158,0.5)';
    }
    ctx.beginPath(); ctx.ellipse(PX, PY, Math.max(0.3, rx), ry, 0, 0, TAU); ctx.fill(); ctx.stroke();
    ctx.fillStyle = 'rgba(255,250,225,' + (0.35 + 0.25 * Math.sin(time * 0.9 + b.ph)).toFixed(3) + ')';
    ctx.beginPath();
    ctx.ellipse(PX - rx * 0.32, PY - ry * 0.38, Math.max(0.3, rx * 0.24), Math.max(0.25, ry * 0.22), 0, 0, TAU);
    ctx.fill();
  }
}

function drawNori(n, time) {
  const R = B.R;
  proj(n.u, n.v, 0);
  const bx = PX, by = PY;
  const sway = Math.sin(time * 0.7 + n.ph) * 0.006;
  proj(n.u + n.lean + sway, n.v, n.h);
  const tx = PX, ty = PY;
  const w1 = n.w * R, w2 = w1 * 0.96, sk = n.skew * R;
  const blx = bx - w1 / 2, brx = bx + w1 / 2, bly = by + sk, bry = by - sk;
  const tlx = tx - w2 / 2, trx = tx + w2 / 2, tly = ty + sk, try_ = ty - sk;

  ctx.beginPath();
  ctx.moveTo(blx, bly);
  ctx.quadraticCurveTo((blx + tlx) / 2 - R * 0.008 * Math.sin(n.ph), (bly + tly) / 2, tlx, tly);
  const seg = n.edge.length;
  for (let i = 1; i <= seg; i++) {
    const f = i / seg;
    ctx.lineTo(lerp(tlx, trx, f), lerp(tly, try_, f) + n.edge[i - 1] * R * 0.03);
  }
  ctx.quadraticCurveTo((brx + trx) / 2 + R * 0.008 * Math.sin(n.ph * 1.7), (bry + try_) / 2, brx, bry);
  ctx.closePath();

  let g = ctx.createLinearGradient(0, ty, 0, by);
  g.addColorStop(0, '#233a29');
  g.addColorStop(0.5, '#131f16');
  g.addColorStop(1, '#0a100b');
  ctx.fillStyle = g;
  ctx.fill();

  g = ctx.createLinearGradient(0, by - (by - ty) * 0.3, 0, by);
  g.addColorStop(0, 'rgba(120,60,14,0)');
  g.addColorStop(1, 'rgba(120,60,14,0.6)');
  ctx.fillStyle = g;
  ctx.fill();

  const hp = clamp(0.5 + (light.x - bx) / (w1 * 7), 0.2, 0.8);
  g = ctx.createLinearGradient(blx, 0, brx, 0);
  g.addColorStop(0, 'rgba(190,225,190,0)');
  g.addColorStop(hp - 0.2, 'rgba(190,225,190,0)');
  g.addColorStop(hp, 'rgba(190,235,200,0.22)');
  g.addColorStop(hp + 0.2, 'rgba(190,225,190,0)');
  g.addColorStop(1, 'rgba(190,225,190,0)');
  ctx.fillStyle = g;
  ctx.fill();

  ctx.strokeStyle = 'rgba(255,190,120,0.16)';
  ctx.lineWidth = 1;
  ctx.stroke();

  ctx.strokeStyle = 'rgba(150,190,150,0.10)';
  ctx.beginPath();
  for (let j = 1; j <= 5; j++) {
    const f = j / 6;
    const x0 = lerp(blx, brx, f), y0 = lerp(bly, bry, f);
    const x1 = lerp(tlx, trx, f), y1 = lerp(tly, try_, f);
    ctx.moveTo(x0, y0);
    ctx.quadraticCurveTo((x0 + x1) / 2 + R * 0.01 * Math.sin(j * 2.3 + n.ph), (y0 + y1) / 2, x1, y1);
  }
  ctx.stroke();

  ctx.strokeStyle = 'rgba(255,200,130,0.25)';
  ctx.beginPath(); ctx.moveTo(blx, bly); ctx.lineTo(brx, bry); ctx.stroke();
}

function drawLeaf(L, time) {
  const ang = L.ang + Math.sin(time * 0.6 + L.ph) * 0.02 - par.x * 0.05;
  const len = L.len * B.R, wid = L.wid * B.R;
  const ca = Math.cos(ang), sa = Math.sin(ang);
  const nx = -sa, ny = ca;
  const M = 14;
  const lx = [], ly = [], rx = [], ry = [], ax = [], ay = [];
  for (let i = 0; i <= M; i++) {
    const s = i / M;
    const bend = L.bend * len * s * s;
    const px = L.x + ca * len * s + nx * bend, py = L.y + sa * len * s + ny * bend;
    const prof = Math.max(0.14 + 0.5 * s, Math.pow(Math.sin(Math.PI * clamp((s - 0.15) / 0.85, 0, 1)), 0.75));
    const hw = wid * 0.5 * prof * (1 + 0.07 * Math.sin(s * 19 + L.ph));
    lx.push(px + nx * hw); ly.push(py + ny * hw);
    rx.push(px - nx * hw); ry.push(py - ny * hw);
    ax.push(px); ay.push(py);
  }
  ctx.beginPath();
  ctx.moveTo(lx[0], ly[0]);
  for (let i = 1; i <= M; i++) ctx.lineTo(lx[i], ly[i]);
  for (let i = M; i >= 0; i--) ctx.lineTo(rx[i], ry[i]);
  ctx.closePath();
  const g = ctx.createLinearGradient(L.x, L.y, ax[M], ay[M]);
  g.addColorStop(0, '#e2ecbc');
  g.addColorStop(0.24, '#cfe19c');
  g.addColorStop(0.34, '#7fb040');
  g.addColorStop(0.7, '#3f8226');
  g.addColorStop(1, '#2a5f1a');
  ctx.fillStyle = g;
  ctx.fill();
  ctx.strokeStyle = 'rgba(15,45,10,0.55)';
  ctx.lineWidth = 1;
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(ax[1], ay[1]);
  for (let i = 2; i <= 12; i++) ctx.lineTo(ax[i], ay[i]);
  ctx.strokeStyle = 'rgba(236,244,190,0.55)';
  ctx.lineWidth = 1.4;
  ctx.stroke();

  ctx.beginPath();
  for (let i = 6; i <= 12; i += 2) {
    ctx.moveTo(ax[i], ay[i]); ctx.lineTo(lx[i + 1], ly[i + 1]);
    ctx.moveTo(ax[i], ay[i]); ctx.lineTo(rx[i + 1], ry[i + 1]);
  }
  ctx.strokeStyle = 'rgba(200,230,150,0.22)';
  ctx.lineWidth = 0.8;
  ctx.stroke();
}

function drawLeaves(time) {
  proj(-0.58, -0.28, 0.02);
  const bx = PX, by = PY;
  for (let i = 0; i < S.leaves.length; i++) {
    const L = S.leaves[i];
    L.x = bx; L.y = by;
    drawLeaf(L, time);
  }
}

function strandPath(s, time, path) {
  const NP = 42;
  const bobc = ripAt(s.cu, s.cv);
  const sway = Math.sin(time * 0.8 + s.ph) * 0.004;
  const ca = Math.cos(s.ang), sa = Math.sin(s.ang);
  for (let i = 0; i <= NP; i++) {
    const t = i / NP - 0.5;
    const l = t * 2 * s.half;
    const u = s.cu + l * ca;
    let v = s.cv + l * sa * 0.55 + s.aw * Math.sin(s.wf * TAU * t + s.ph) + sway;
    const h0 = moundH(u, v);
    const wv = Math.sin(s.cf * TAU * t + s.cph);
    v += Math.sin(s.cf * TAU * t + s.cph2) * 0.022;
    let h = 0.007 + h0 * (0.82 + 0.18 * Math.sin(s.wf * 4.3 * t + s.ph)) + wv * s.ca * Math.min(1, 0.4 + h0 * 6);
    if (h0 > 0.01) h += s.lift * Math.min(1, h0 * 8);
    h += bobc * 0.012;
    proj(u, v, h);
    if (i === 0) path.moveTo(PX, PY); else path.lineTo(PX, PY);
  }
}

function drawNoodles(time) {
  const R = B.R;
  proj(MOUND.u, MOUND.v + 0.06, 0);
  ctx.save();
  ctx.translate(PX, PY);
  ctx.scale(1, B.k);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, B.brx * 0.75);
  g.addColorStop(0, 'rgba(45,18,4,0.75)');
  g.addColorStop(1, 'rgba(45,18,4,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(0, 0, B.brx * 0.75, 0, TAU); ctx.fill();
  ctx.restore();

  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  const list = S.strands;
  for (let i = 0; i < list.length; i++) {
    const s = list[i];
    const path = new Path2D();
    strandPath(s, time, path);
    const hm = moundH(s.cu, s.cv) / MOUND.h;
    const lit = clamp(0.25 + hm * 0.75 + (s.tone - 0.5) * 0.25, 0, 1);
    const lw = s.w * R;
    ctx.strokeStyle = 'rgba(60,28,6,0.6)';
    ctx.lineWidth = lw * 1.5;
    ctx.stroke(path);
    ctx.strokeStyle = rgbStr(mixc(NOODLE_DARK, NOODLE_LIGHT, lit));
    ctx.lineWidth = lw;
    ctx.stroke(path);
    ctx.save();
    ctx.translate(0, -lw * 0.2);
    ctx.strokeStyle = 'rgba(255,244,210,' + (0.10 + 0.32 * lit).toFixed(3) + ')';
    ctx.lineWidth = lw * 0.34;
    ctx.stroke(path);
    ctx.restore();
  }
}

const SLAB_C = [[-1, -1], [1, -1], [1, 1], [-1, 1]];
function drawSlab(s, time) {
  const rise = s.rise + bobAt(s.u, s.v, s.ph, time);
  const ca = Math.cos(s.ang), sa = Math.sin(s.ang);
  const bx = [], by = [], tx = [], ty = [], zz = [];
  for (let i = 0; i < 4; i++) {
    const x = SLAB_C[i][0] * s.lx * 0.5, z = SLAB_C[i][1] * s.lz * 0.5;
    const dx = x * ca - z * sa, dz = x * sa + z * ca;
    projW(s.u, s.v, dx, dz, rise); bx.push(PX); by.push(PY);
    projW(s.u, s.v, dx, dz, rise + s.th); tx.push(PX); ty.push(PY);
    zz.push(dz);
  }
  const order = [0, 1, 2, 3].sort((a, b) => (zz[a] + zz[(a + 1) % 4]) - (zz[b] + zz[(b + 1) % 4]));
  for (let n = 0; n < 4; n++) {
    const i = order[n], j = (i + 1) % 4;
    ctx.beginPath();
    ctx.moveTo(bx[i], by[i]); ctx.lineTo(bx[j], by[j]); ctx.lineTo(tx[j], ty[j]); ctx.lineTo(tx[i], ty[i]);
    ctx.closePath();
    ctx.fillStyle = rgbStr(mixc(s.sideDark, s.side, clamp(0.5 + (zz[i] + zz[j]) * 2.0, 0, 1)));
    ctx.fill();
  }
  ctx.beginPath();
  ctx.moveTo(tx[0], ty[0]);
  for (let i = 1; i < 4; i++) ctx.lineTo(tx[i], ty[i]);
  ctx.closePath();
  const g = ctx.createLinearGradient(tx[0], ty[0], tx[2], ty[2]);
  g.addColorStop(0, rgbStr(s.top1));
  g.addColorStop(1, rgbStr(s.top2));
  ctx.fillStyle = g;
  ctx.fill();
  ctx.strokeStyle = 'rgba(255,230,180,0.22)';
  ctx.lineWidth = 1;
  ctx.stroke();

  const top = rise + s.th;
  const loc = (fx, fz) => {
    const x = fx * s.lx, z = fz * s.lz;
    projW(s.u, s.v, x * ca - z * sa, x * sa + z * ca, top);
  };
  ctx.lineCap = 'round';
  if (s.marks) {
    ctx.strokeStyle = 'rgba(60,28,8,0.5)';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    for (let j = -1; j <= 1; j++) {
      loc(j * 0.3 - 0.09, -0.42); ctx.moveTo(PX, PY);
      loc(j * 0.3 + 0.09, 0.42); ctx.lineTo(PX, PY);
    }
    ctx.stroke();
  }
  if (s.fibers) {
    ctx.strokeStyle = 'rgba(90,55,20,0.35)';
    ctx.lineWidth = 0.9;
    ctx.beginPath();
    for (const fz of [-0.18, 0.18]) {
      loc(-0.42, fz); ctx.moveTo(PX, PY);
      loc(0.42, fz); ctx.lineTo(PX, PY);
    }
    ctx.stroke();
  }
  ctx.strokeStyle = 'rgba(255,235,190,0.32)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  loc(-0.34, -0.3); ctx.moveTo(PX, PY);
  loc(0.22, -0.3); ctx.lineTo(PX, PY);
  ctx.stroke();
}

function drawMush(m, time) {
  const R = B.R, k = B.k;
  proj(m.u, m.v, m.h + bobAt(m.u, m.v, m.ph, time));
  const x = PX, y = PY;
  const r = m.r * R, ry = Math.max(0.5, r * k * 1.08), th = r * 0.30;

  proj(m.u, m.v, 0);
  ctx.fillStyle = 'rgba(30,10,0,0.35)';
  ctx.beginPath(); ctx.ellipse(PX + r * 0.1, PY + ry * 0.35, r * 1.08, ry * 1.12, 0, 0, TAU); ctx.fill();

  ctx.beginPath();
  ctx.moveTo(x - r, y);
  ctx.lineTo(x - r, y + th);
  ctx.ellipse(x, y + th, r, ry, 0, Math.PI, 0, true);
  ctx.lineTo(x + r, y);
  ctx.closePath();
  let g = ctx.createLinearGradient(x - r, 0, x + r, 0);
  g.addColorStop(0, '#3a1f0e');
  g.addColorStop(0.5, '#5a3418');
  g.addColorStop(1, '#24120a');
  ctx.fillStyle = g;
  ctx.fill();
  ctx.strokeStyle = 'rgba(226,196,150,0.45)';
  ctx.lineWidth = 1.1;
  ctx.beginPath(); ctx.ellipse(x, y + th, r, ry, 0, 0.12, Math.PI - 0.12, false); ctx.stroke();

  ctx.save();
  ctx.translate(x, y);
  ctx.scale(1, ry / r);
  g = ctx.createRadialGradient(-r * 0.2, -r * 0.25, r * 0.05, 0, 0, r);
  g.addColorStop(0, '#8a5a2c');
  g.addColorStop(0.55, '#5f3719');
  g.addColorStop(1, '#33190a');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(0, 0, r, 0, TAU); ctx.fill();

  ctx.lineCap = 'round';
  ctx.strokeStyle = 'rgba(236,212,170,0.75)';
  ctx.lineWidth = r * 0.09;
  ctx.beginPath();
  for (let i = 0; i < 3; i++) {
    const a = m.rot + i * Math.PI / 3;
    const c = Math.cos(a), s = Math.sin(a);
    ctx.moveTo(-c * r * 0.82, -s * r * 0.82);
    ctx.quadraticCurveTo(-s * r * 0.12, c * r * 0.12, c * r * 0.82, s * r * 0.82);
  }
  ctx.stroke();
  ctx.strokeStyle = 'rgba(90,50,20,0.5)';
  ctx.lineWidth = r * 0.03;
  ctx.stroke();

  g = ctx.createRadialGradient(-r * 0.3, -r * 0.35, 0, -r * 0.3, -r * 0.35, r * 0.4);
  g.addColorStop(0, 'rgba(255,214,160,0.32)');
  g.addColorStop(1, 'rgba(255,214,160,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(-r * 0.3, -r * 0.35, r * 0.4, 0, TAU); ctx.fill();
  ctx.restore();
}

function drawCorn(time) {
  const R = B.R, k = B.k;
  for (let i = 0; i < S.corn.length; i++) {
    const c = S.corn[i];
    projW(c.u, c.v, c.dx, c.dz, c.h + bobAt(c.u, c.v, c.ph, time));
    const rx = c.r * R, ry = Math.max(0.5, rx * k * 1.2);
    ctx.fillStyle = 'rgba(60,28,4,0.55)';
    ctx.beginPath(); ctx.ellipse(PX, PY + ry * 0.55, rx, ry, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = rgbStr(c.col);
    ctx.beginPath(); ctx.ellipse(PX, PY, rx, ry, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = 'rgba(255,248,190,0.8)';
    ctx.beginPath(); ctx.ellipse(PX - rx * 0.3, PY - ry * 0.35, rx * 0.35, ry * 0.3, 0, 0, TAU); ctx.fill();
  }
}

function drawFloaters(time) {
  const R = B.R, k = B.k, fl = S.floaters;
  for (let i = 0; i < fl.length; i++) {
    const f = fl[i];
    proj(f.u, f.v, f.hm + bobAt(f.u, f.v, f.ph, time));
    const x = PX, y = PY;
    if (f.type === 0) {
      const rx = f.r * R, ry = Math.max(0.6, rx * k * 1.15);
      ctx.fillStyle = 'rgba(20,10,2,0.35)';
      ctx.beginPath(); ctx.ellipse(x + 1, y + ry * 0.6, rx, ry, 0, 0, TAU); ctx.fill();
      ctx.fillStyle = f.c1;
      ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, TAU); ctx.fill();
      ctx.strokeStyle = f.c2;
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.ellipse(x, y, rx * 0.66, ry * 0.66, 0, 0, TAU); ctx.stroke();
      ctx.fillStyle = 'rgba(215,238,160,0.85)';
      ctx.beginPath(); ctx.ellipse(x, y, rx * 0.46, ry * 0.46, 0, 0, TAU); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,230,0.5)';
      ctx.beginPath(); ctx.ellipse(x - rx * 0.4, y - ry * 0.45, rx * 0.22, ry * 0.16, 0, 0, TAU); ctx.fill();
    } else {
      ctx.fillStyle = f.dark ? '#3a2c1e' : '#f1e3c2';
      ctx.beginPath();
      ctx.ellipse(x, y, Math.max(0.6, f.r * R), Math.max(0.4, f.r * R * 0.55), f.rot, 0, TAU);
      ctx.fill();
    }
  }
}

function drawContents() {
  const time = T;
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, 0, W, B.cy);
  ctx.moveTo(B.cx + B.irx, B.cy);
  ctx.ellipse(B.cx, B.cy, B.irx, B.iry, 0, 0, TAU);
  ctx.closePath();
  ctx.clip();
  drawBeads(time);
  for (let i = 0; i < S.nori.length; i++) drawNori(S.nori[i], time);
  drawLeaves(time);
  drawNoodles(time);
  for (let i = 0; i < S.slabs.length; i++) drawSlab(S.slabs[i], time);
  for (let i = 0; i < S.mush.length; i++) drawMush(S.mush[i], time);
  drawCorn(time);
  drawFloaters(time);
  ctx.restore();
}

/*@@PART5@@*/

/* ---------- steam, motes, finish ---------- */
function drawSteam() {
  const R = B.R;
  for (let i = 0; i < steam.length; i++) {
    const p = steam[i];
    const f = p.age / p.life;
    const a = p.peak * smooth(0, 0.22, f) * (1 - smooth(0.5, 1, f));
    if (a < 0.004) continue;
    const rr = lerp(p.r0, p.r1, 1 - Math.pow(1 - f, 1.6));
    const yn = Math.max(0, (B.bcy - p.y) / R);
    const c = clamp(yn * 1.6 - 0.3, 0, 2);
    const ti = Math.min(1, Math.floor(c)), fr = c - ti;
    const cs = Math.cos(p.rot) * dpr, sn = Math.sin(p.rot) * dpr;
    ctx.setTransform(cs, sn, -sn, cs, p.x * dpr, p.y * dpr);
    ctx.globalAlpha = a * (1 - fr);
    if (ctx.globalAlpha > 0.002) ctx.drawImage(sprites[ti][p.v], -rr, -rr * 1.25, rr * 2, rr * 2.5);
    if (fr > 0.02) {
      ctx.globalAlpha = a * fr;
      ctx.drawImage(sprites[ti + 1][p.v], -rr, -rr * 1.25, rr * 2, rr * 2.5);
    }
  }
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.globalAlpha = 1;
}

function drawMotes() {
  ctx.globalCompositeOperation = 'lighter';
  const lim = B.R * 2.0;
  for (let i = 0; i < motes.length; i++) {
    const m = motes[i];
    const d = Math.hypot(m.x - B.cx, (m.y - B.cy) * 1.3) / lim;
    const prox = Math.exp(-d * d);
    const a = (0.05 + 0.5 * prox) * (0.5 + 0.5 * Math.sin(T * m.tw + m.ph));
    if (a < 0.01) continue;
    ctx.fillStyle = 'rgba(255,196,130,' + a.toFixed(3) + ')';
    ctx.beginPath(); ctx.arc(m.x, m.y, m.r, 0, TAU); ctx.fill();
  }
  ctx.globalCompositeOperation = 'source-over';
}

function drawFinish() {
  let g = ctx.createLinearGradient(0, 0, 0, H * 0.4);
  g.addColorStop(0, 'rgba(2,1,1,0.55)');
  g.addColorStop(1, 'rgba(2,1,1,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H * 0.4);

  const vy = H * 0.56;
  g = ctx.createRadialGradient(W / 2, vy, Math.min(W, H) * 0.28, W / 2, vy, Math.hypot(W, H) * 0.58);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.6, 'rgba(0,0,0,0.25)');
  g.addColorStop(1, 'rgba(0,0,0,0.78)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  if (grainPat) {
    if (!reduced && (frameNo & 1) === 0) {
      grainX = (Math.random() * 128) | 0;
      grainY = (Math.random() * 128) | 0;
    }
    ctx.save();
    ctx.translate(-grainX, -grainY);
    ctx.fillStyle = grainPat;
    ctx.fillRect(0, 0, W + 128, H + 128);
    ctx.restore();
  }
}

/* ---------- render ---------- */
function render() {
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.lineCap = 'butt';
  ctx.lineJoin = 'round';

  flick = 1 + 0.035 * Math.sin(T * 2.3) + 0.025 * Math.sin(T * 5.1 + 1.3) + 0.015 * Math.sin(T * 9.7 + 2.1);
  LX = clamp((light.x - B.cx) / B.R, -1.6, 1.6);
  LY = clamp((light.y - B.cy) / B.R, -1.8, 1.6);

  ctx.drawImage(bg, -bgM + par.x * 10, -bgM + par.y * 6, W + bgM * 2, H + bgM * 2);
  drawAmbient();
  drawBowl();
  drawBroth();
  drawContents();
  drawLip();
  drawSteam();
  drawMotes();
  drawFinish();
  frameNo++;
}

function renderStatic() {
  T = 2.6;
  par.x = 0; par.y = 0;
  ptr.active = false; ptr.vx = 0; ptr.vy = 0;
  light.x = base.cx - 0.45 * base.R;
  light.y = base.cy - base.R;
  ripples.length = 0;
  layout();
  render();
}

/* ---------- lifecycle ---------- */
let rafId = 0, lastNow = 0;
function loop(now) {
  rafId = requestAnimationFrame(loop);
  const dt = lastNow ? Math.min(0.05, Math.max(0.001, (now - lastNow) / 1000)) : 0.016;
  lastNow = now;
  T += dt;
  update(dt);
  render();
}

function start() {
  cancelAnimationFrame(rafId);
  rafId = 0;
  if (reduced) { renderStatic(); return; }
  lastNow = 0;
  rafId = requestAnimationFrame(loop);
}

function resize() {
  W = Math.max(1, window.innerWidth);
  H = Math.max(1, window.innerHeight);
  dpr = Math.min(window.devicePixelRatio || 1, 2);
  while (W * H * dpr * dpr > 4.5e6 && dpr > 1) dpr = Math.max(1, dpr * 0.85);
  canvas.width = Math.round(W * dpr);
  canvas.height = Math.round(H * dpr);
  computeBase();
  layout();
  buildBg();
  initMotes();
  if (!ptr.active) {
    light.x = base.cx - 0.45 * base.R;
    light.y = base.cy - base.R;
  }
  prewarmSteam(6.5);
  if (reduced) renderStatic();
}

function onPointerMove(e) {
  if (reduced) return;
  const x = e.clientX, y = e.clientY, now = performance.now();
  if (ptr.active) {
    const dtm = Math.max(4, now - ptr.ms) / 1000;
    ptr.vx = clamp(lerp(ptr.vx, (x - ptr.x) / dtm, 0.4), -3000, 3000);
    ptr.vy = clamp(lerp(ptr.vy, (y - ptr.y) / dtm, 0.4), -3000, 3000);
  }
  ptr.x = x; ptr.y = y; ptr.ms = now; ptr.t = T;
  ptr.active = true;
  ptr.touch = e.pointerType === 'touch' || e.pointerType === 'pen';
}

function onPointerDown(e) {
  if (reduced) return;
  onPointerMove(e);
  const u = (e.clientX - B.bcx) / B.brx, v = (e.clientY - B.bcy) / B.bry;
  if (u * u + v * v < 1.0) addRipple(u, v, 1.0, 0.6, 2.6);
  else addRipple(0, 0, 0.6, 0.5, 2.4);
  for (let i = 0; i < 12; i++) emitFromBroth(true);
}

function onReducedChange() {
  reduced = mq.matches;
  ptr.active = false;
  ripples.length = 0;
  prewarmSteam(6.5);
  start();
}

buildScene();
buildSprites();
buildGrain();
resize();
start();

window.addEventListener('resize', () => { resize(); if (!reduced && !rafId) start(); });
window.addEventListener('pointermove', onPointerMove, { passive: true });
window.addEventListener('pointerdown', onPointerDown, { passive: true });
document.documentElement.addEventListener('pointerleave', e => { if (e.pointerType === 'mouse') ptr.active = false; });
window.addEventListener('blur', () => { ptr.active = false; });
if (mq.addEventListener) mq.addEventListener('change', onReducedChange);
else if (mq.addListener) mq.addListener(onReducedChange);

