1162	      ctx.ellipse(x, y, Math.max(0.6, f.r * R), Math.max(0.4, f.r * R * 0.55), f.rot, 0, TAU);
1163	      ctx.fill();
1164	    }
1165	  }
1166	}
1167	
1168	function drawContents() {
1169	  const time = T;
1170	  ctx.save();
1171	  ctx.beginPath();
1172	  ctx.rect(0, 0, W, B.cy);
1173	  ctx.moveTo(B.cx + B.irx, B.cy);
1174	  ctx.ellipse(B.cx, B.cy, B.irx, B.iry, 0, 0, TAU);
1175	  ctx.closePath();
1176	  ctx.clip();
1177	  drawBeads(time);
1178	  for (let i = 0; i < S.nori.length; i++) drawNori(S.nori[i], time);
1179	  drawLeaves(time);
1180	  drawNoodles(time);
1181	  for (let i = 0; i < S.slabs.length; i++) drawSlab(S.slabs[i], time);
1182	  for (let i = 0; i < S.mush.length; i++) drawMush(S.mush[i], time);
1183	  drawCorn(time);
1184	  drawFloaters(time);
1185	  ctx.restore();
1186	}
1187	
1188	/* ---------- steam, motes, finish ---------- */
1189	function drawSteam() {
1190	  const R = B.R;
1191	  for (let i = 0; i < steam.length; i++) {
1192	    const p = steam[i];
1193	    const f = p.age / p.life;
1194	    const a = p.peak * smooth(0, 0.22, f) * (1 - smooth(0.5, 1, f));
1195	    if (a < 0.004) continue;
1196	    const rr = lerp(p.r0, p.r1, 1 - Math.pow(1 - f, 1.6));
1197	    const yn = Math.max(0, (B.bcy - p.y) / R);
1198	    const c = clamp(yn * 1.6 - 0.3, 0, 2);
1199	    const ti = Math.min(1, Math.floor(c)), fr = c - ti;
1200	    const cs = Math.cos(p.rot) * dpr, sn = Math.sin(p.rot) * dpr;
1201	    ctx.setTransform(cs, sn, -sn, cs, p.x * dpr, p.y * dpr);
1202	    ctx.globalAlpha = a * (1 - fr);
1203	    if (ctx.globalAlpha > 0.002) ctx.drawImage(sprites[ti][p.v], -rr, -rr * 1.25, rr * 2, rr * 2.5);
1204	    if (fr > 0.02) {
1205	      ctx.globalAlpha = a * fr;
1206	      ctx.drawImage(sprites[ti + 1][p.v], -rr, -rr * 1.25, rr * 2, rr * 2.5);
1207	    }
1208	  }
1209	  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
1210	  ctx.globalAlpha = 1;
1211	}
1212	
1213	function drawMotes() {
1214	  ctx.globalCompositeOperation = 'lighter';
1215	  const lim = B.R * 2.0;
1216	  for (let i = 0; i < motes.length; i++) {
1217	    const m = motes[i];
1218	    const d = Math.hypot(m.x - B.cx, (m.y - B.cy) * 1.3) / lim;
1219	    const prox = Math.exp(-d * d);
1220	    const a = (0.05 + 0.5 * prox) * (0.5 + 0.5 * Math.sin(T * m.tw + m.ph));
1221	    if (a < 0.01) continue;
1222	    ctx.fillStyle = 'rgba(255,196,130,' + a.toFixed(3) + ')';
1223	    ctx.beginPath(); ctx.arc(m.x, m.y, m.r, 0, TAU); ctx.fill();
1224	  }
1225	  ctx.globalCompositeOperation = 'source-over';
1226	}
1227	
1228	function drawFinish() {
1229	  let g = ctx.createLinearGradient(0, 0, 0, H * 0.4);
1230	  g.addColorStop(0, 'rgba(2,1,1,0.55)');
1231	  g.addColorStop(1, 'rgba(2,1,1,0)');
1232	  ctx.fillStyle = g;
1233	  ctx.fillRect(0, 0, W, H * 0.4);
1234	
1235	  const vy = H * 0.56;
1236	  g = ctx.createRadialGradient(W / 2, vy, Math.min(W, H) * 0.28, W / 2, vy, Math.hypot(W, H) * 0.58);
1237	  g.addColorStop(0, 'rgba(0,0,0,0)');
1238	  g.addColorStop(0.6, 'rgba(0,0,0,0.25)');
1239	  g.addColorStop(1, 'rgba(0,0,0,0.78)');
1240	  ctx.fillStyle = g;
1241	  ctx.fillRect(0, 0, W, H);
1242	
1243	  if (grainPat) {
1244	    if (!reduced && (frameNo & 1) === 0) {
1245	      grainX = (Math.random() * 128) | 0;
1246	      grainY = (Math.random() * 128) | 0;
1247	    }
1248	    ctx.save();
1249	    ctx.translate(-grainX, -grainY);
1250	    ctx.fillStyle = grainPat;
1251	    ctx.fillRect(0, 0, W + 128, H + 128);
1252	    ctx.restore();
1253	  }
1254	}
1255	
1256	/* ---------- render ---------- */
1257	function render() {
1258	  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
1259	  ctx.globalAlpha = 1;
1260	  ctx.globalCompositeOperation = 'source-over';
1261	  ctx.lineCap = 'butt';
1262	  ctx.lineJoin = 'round';
1263	
1264	  flick = 1 + 0.035 * Math.sin(T * 2.3) + 0.025 * Math.sin(T * 5.1 + 1.3) + 0.015 * Math.sin(T * 9.7 + 2.1);
1265	  LX = clamp((light.x - B.cx) / B.R, -1.6, 1.6);
1266	  LY = clamp((light.y - B.cy) / B.R, -1.8, 1.6);
1267	
1268	  ctx.drawImage(bg, -bgM + par.x * 10, -bgM + par.y * 6, W + bgM * 2, H + bgM * 2);
1269	  drawAmbient();
1270	  drawBowl();
1271	  drawBroth();
1272	  drawContents();
1273	  drawLip();
1274	  drawSteam();
1275	  drawMotes();
1276	  drawFinish();
1277	  frameNo++;
1278	}
1279	
1280	function renderStatic() {
1281	  T = 2.6;
1282	  par.x = 0; par.y = 0;
1283	  ptr.active = false; ptr.vx = 0; ptr.vy = 0;
1284	  light.x = base.cx - 0.45 * base.R;
1285	  light.y = base.cy - base.R;
1286	  ripples.length = 0;
1287	  layout();
1288	  render();
1289	}
1290	
1291	/* ---------- lifecycle ---------- */
1292	let rafId = 0, lastNow = 0;
1293	function loop(now) {
1294	  rafId = requestAnimationFrame(loop);
1295	  const dt = lastNow ? Math.min(0.05, Math.max(0.001, (now - lastNow) / 1000)) : 0.016;
1296	  lastNow = now;
1297	  T += dt;
1298	  update(dt);
1299	  render();
1300	}
1301	
1302	function start() {
1303	  cancelAnimationFrame(rafId);
1304	  rafId = 0;
1305	  if (reduced) { renderStatic(); return; }
1306	  lastNow = 0;
1307	  rafId = requestAnimationFrame(loop);
1308	}
1309	
1310	function resize() {
1311	  W = Math.max(1, window.innerWidth);
1312	  H = Math.max(1, window.innerHeight);
1313	  dpr = Math.min(window.devicePixelRatio || 1, 2);
1314	  while (W * H * dpr * dpr > 4.5e6 && dpr > 1) dpr = Math.max(1, dpr * 0.85);
1315	  canvas.width = Math.round(W * dpr);
1316	  canvas.height = Math.round(H * dpr);
1317	  computeBase();
1318	  layout();
1319	  buildBg();
1320	  initMotes();
1321	  if (!ptr.active) {
1322	    light.x = base.cx - 0.45 * base.R;
1323	    light.y = base.cy - base.R;
1324	  }
1325	  prewarmSteam(6.5);
1326	  if (reduced) renderStatic();
1327	}
1328	
1329	function onPointerMove(e) {
1330	  if (reduced) return;
1331	  const x = e.clientX, y = e.clientY, now = performance.now();
1332	  if (ptr.active) {
1333	    const dtm = Math.max(4, now - ptr.ms) / 1000;
1334	    ptr.vx = clamp(lerp(ptr.vx, (x - ptr.x) / dtm, 0.4), -3000, 3000);
1335	    ptr.vy = clamp(lerp(ptr.vy, (y - ptr.y) / dtm, 0.4), -3000, 3000);
1336	  }
1337	  ptr.x = x; ptr.y = y; ptr.ms = now; ptr.t = T;
1338	  ptr.active = true;
1339	  ptr.touch = e.pointerType === 'touch' || e.pointerType === 'pen';
1340	}
1341	
1342	function onPointerDown(e) {
1343	  if (reduced) return;
1344	  onPointerMove(e);
1345	  const u = (e.clientX - B.bcx) / B.brx, v = (e.clientY - B.bcy) / B.bry;
1346	  if (u * u + v * v < 1.0) addRipple(u, v, 1.0, 0.6, 2.6);
1347	  else addRipple(0, 0, 0.6, 0.5, 2.4);
1348	  for (let i = 0; i < 12; i++) emitFromBroth(true);
1349	}
1350	
1351	function onReducedChange() {
1352	  reduced = mq.matches;
1353	  ptr.active = false;
1354	  ripples.length = 0;
1355	  prewarmSteam(6.5);
1356	  start();
1357	}
1358	
1359	buildScene();
1360	buildSprites();
1361	buildGrain();
1362	resize();
1363	start();
1364	
1365	window.addEventListener('resize', () => { resize(); if (!reduced && !rafId) start(); });
1366	window.addEventListener('pointermove', onPointerMove, { passive: true });
1367	window.addEventListener('pointerdown', onPointerDown, { passive: true });
1368	document.documentElement.addEventListener('pointerleave', e => { if (e.pointerType === 'mouse') ptr.active = false; });
1369	window.addEventListener('blur', () => { ptr.active = false; });
1370	if (mq.addEventListener) mq.addEventListener('change', onReducedChange);
1371	else if (mq.addListener) mq.addListener(onReducedChange);
1372	
1373	})();
1374	</script>
